   306→impl FromTxWithEncoded<TxEip7702> for TxEnv {
   307→    fn from_encoded_tx(tx: &TxEip7702, sender: Address, _encoded: Bytes) -> Self {
   308→        Self::from_recovered_tx(tx, sender)
   309→    }
