   174→        }
   175→    }
   176→
   177→    /// Invokes the state hook with the outcome of the given closure, forwards error if any.
   178→    pub fn try_on_state_with<'a, F, E>(&mut self, f: F) -> Result<(), E>
   179→    where
   180→        F: FnOnce() -> Result<(StateChangeSource, Cow<'a, EvmState>), E>,
   181→    {
